document.querySelector(".ind-swiper")&&new Swiper(".ind-swiper",{slidesPerView:1.2,spaceBetween:16,pagination:{el:".ind-swiper .swiper-pagination"},breakpoints:{640:{slidesPerView:2.2},1024:{slidesPerView:3.2},1280:{slidesPerView:4.2}}});const urlMap={wp:"yourdomain.com/wp-admin",shopify:"yourdomain.myshopify.com/admin",drupal:"yourdomain.com/admin/content",custom:"cms.yourdomain.com/dashboard"};document.querySelectorAll(".ptab").forEach(e=>{e.addEventListener("click",()=>{const t=e.dataset.panel;document.querySelectorAll(".ptab").forEach(e=>e.classList.remove("active")),document.querySelectorAll(".cms-panel").forEach(e=>e.classList.remove("active")),e.classList.add("active"),document.getElementById("panel-"+t).classList.add("active"),document.getElementById("cmsUrlBar").textContent=urlMap[t]||""})});const obs=new IntersectionObserver(e=>{e.forEach((e,t)=>{e.isIntersecting&&(setTimeout(()=>e.target.classList.add("visible")),obs.unobserve(e.target))})},{threshold:.1});document.querySelectorAll(".reveal").forEach(e=>obs.observe(e));